#include <valarray>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::valarray<int> values{1, 2, 3, 4, 5, 6};
    {
        auto slice = values[std::slice(0, 2, 2)];
        slice = 8;
        slice += std::valarray<int>(1, 2);
        slice -= std::valarray<int>(1, 2);
        slice *= std::valarray<int>(2, 2);
        slice /= std::valarray<int>(2, 2);
        slice %= std::valarray<int>(7, 2);
        slice ^= std::valarray<int>(1, 2);
        slice &= std::valarray<int>(7, 2);
        slice |= std::valarray<int>(2, 2);
        slice <<= std::valarray<int>(1, 2);
        slice >>= std::valarray<int>(1, 2);
    }
    std::valarray<std::size_t> sizes{2, 2}, strides{3, 1};
    std::gslice selector{0, sizes, strides};
    {
        auto grid = values[selector];
        grid = 4;
        grid += std::valarray<int>(1, 4);
        grid -= std::valarray<int>(1, 4);
        grid *= std::valarray<int>(2, 4);
        grid /= std::valarray<int>(2, 4);
        grid %= std::valarray<int>(7, 4);
        grid ^= std::valarray<int>(1, 4);
        grid &= std::valarray<int>(7, 4);
        grid |= std::valarray<int>(2, 4);
        grid <<= std::valarray<int>(1, 4);
        grid >>= std::valarray<int>(1, 4);
    }
    std::valarray<std::size_t> indices{1, 4};
    {
        auto selected = values[indices];
        selected = 3;
        selected += std::valarray<int>(1, 2);
        selected -= std::valarray<int>(1, 2);
        selected *= std::valarray<int>(2, 2);
        selected /= std::valarray<int>(2, 2);
        selected %= std::valarray<int>(7, 2);
        selected ^= std::valarray<int>(1, 2);
        selected &= std::valarray<int>(7, 2);
        selected |= std::valarray<int>(2, 2);
        selected <<= std::valarray<int>(1, 2);
        selected >>= std::valarray<int>(1, 2);
    }
    std::valarray<bool> mask{true, false, false, false, false, true};
    {
        auto selected = values[mask];
        selected = 2;
        selected += std::valarray<int>(1, 2);
        selected -= std::valarray<int>(1, 2);
        selected *= std::valarray<int>(2, 2);
        selected /= std::valarray<int>(2, 2);
        selected %= std::valarray<int>(7, 2);
        selected ^= std::valarray<int>(1, 2);
        selected &= std::valarray<int>(7, 2);
        selected |= std::valarray<int>(2, 2);
        selected <<= std::valarray<int>(1, 2);
        selected >>= std::valarray<int>(1, 2);
    }
    std::valarray<int> other{9, 10};
    values.swap(other);
    assert(values.size() == 2 && values[0] == 9);
}
